        /// <summary>
        /// Configures the HttpClients.
        /// </summary>
        /// <param name="client"></param>
        /// <param name="builder"></param>
        /// <returns></returns>
        public HostConfiguration AddApiHttpClients
        (
            Action<HttpClient>? client = null, Action<IHttpClientBuilder>? builder = null)
        {
            if (client == null)
                client = c => c.BaseAddress = new Uri(ClientUtils.BASE_ADDRESS);

            List<IHttpClientBuilder> builders = new List<IHttpClientBuilder>();

            builders.Add(_services.AddHttpClient<IAPIClientsApi, APIClientsApi>(client));
            builders.Add(_services.AddHttpClient<IApplicationsApi, ApplicationsApi>(client));
            builders.Add(_services.AddHttpClient<IApplicationsSettingsApi, ApplicationsSettingsApi>(client));
            builders.Add(_services.AddHttpClient<IApplicationsTilesApi, ApplicationsTilesApi>(client));
            builders.Add(_services.AddHttpClient<IDomainsApi, DomainsApi>(client));
            builders.Add(_services.AddHttpClient<IEdFiSyncApi, EdFiSyncApi>(client));
            builders.Add(_services.AddHttpClient<IInvitationsApi, InvitationsApi>(client));
            builders.Add(_services.AddHttpClient<IJobExecutionsApi, JobExecutionsApi>(client));
            builders.Add(_services.AddHttpClient<IOnboardingStepsApi, OnboardingStepsApi>(client));
            builders.Add(_services.AddHttpClient<IOnboardingStepsConnectionsApi, OnboardingStepsConnectionsApi>(client));
            builders.Add(_services.AddHttpClient<IOrganizationsApi, OrganizationsApi>(client));
            builders.Add(_services.AddHttpClient<IPartnershipsApi, PartnershipsApi>(client));
            builders.Add(_services.AddHttpClient<ISectionsApi, SectionsApi>(client));
            builders.Add(_services.AddHttpClient<ISettingsApi, SettingsApi>(client));
            builders.Add(_services.AddHttpClient<IStaffClassificationsApi, StaffClassificationsApi>(client));
            builders.Add(_services.AddHttpClient<ISubscriptionsApi, SubscriptionsApi>(client));
            builders.Add(_services.AddHttpClient<ITenantBrandingApi, TenantBrandingApi>(client));
            builders.Add(_services.AddHttpClient<ITenantInstancesApi, TenantInstancesApi>(client));
            builders.Add(_services.AddHttpClient<ITenantSecurityScoreSyncApi, TenantSecurityScoreSyncApi>(client));
            builders.Add(_services.AddHttpClient<ITenantSettingTypesApi, TenantSettingTypesApi>(client));
            builders.Add(_services.AddHttpClient<ITenantsApi, TenantsApi>(client));
            builders.Add(_services.AddHttpClient<IUsersApi, UsersApi>(client));
            builders.Add(_services.AddHttpClient<IUsersEducationOrganizationsApi, UsersEducationOrganizationsApi>(client));
            builders.Add(_services.AddHttpClient<IUsersLicensesApi, UsersLicensesApi>(client));
            builders.Add(_services.AddHttpClient<IUsersSectionsApi, UsersSectionsApi>(client));
            builders.Add(_services.AddHttpClient<IV1Api, V1Api>(client));
            builders.Add(_services.AddHttpClient<IWebhooksApi, WebhooksApi>(client));
            
            if (builder != null)
                foreach (IHttpClientBuilder instance in builders)
                    builder(instance);

            HttpClientsAdded = true;

            return this;
        }

